CREATE FUNCTION dbo.HESAB_ANBAR (@dt2 int,@KOL int, @ANBAR int) RETURNS TABLE AS RETURN ( SELECT     dbo.DEED_DTL.HES_K, dbo.DEED_DTL.HES_M, SUM(dbo.DEED_DTL.BED - dbo.DEED_DTL.BES) AS mand, dbo.DEED_DTL.HES_T, dbo.DEED_DTL.HES FROM         dbo.DEED_DTL INNER JOIN    dbo.DEED_HED ON dbo.DEED_DTL.N_S = dbo.DEED_HED.N_S WHERE     (dbo.DEED_HED.DATE_S <= @dt2) GROUP BY dbo.DEED_DTL.HES_K, dbo.DEED_DTL.HES_M, dbo.DEED_DTL.HES_T, dbo.DEED_DTL.HES HAVING      (dbo.DEED_DTL.HES_K = @KOL) AND (dbo.DEED_DTL.HES_M = @ANBAR) )
